import { Mesh, PlaneGeometry, MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {string} [imageUrl]
 * @property {Array<{ name: string, params: any, trigger: string }>} [cinematicPrimitives]
 * @property {any} [textContent]
 * @property {any} [intent]
 */

/**
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {{ loadTexture: (url:string)=>Promise<any> }} textureLoader
 * @property {{ loadGLB: (url:string)=>Promise<any> }} glbLoader
 * @property {any} fontAtlas
 * @property {Record<string, (target:any, params:any)=>{timeline:any, cleanup:()=>void}>} primitives
 * @property {(event:string, payload:any)=>void} emit
 * @property {string} [tier]
 */

/**
 * Creates a textured plane node.
 *
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  // Root container – a Group to hold potential future children
  const { Group } = ctx.THREE;
  const root = new Group();

  // Geometry & material
  const geometry = new PlaneGeometry(7, 6); // default size; can be adjusted if needed
  const material = new MeshBasicNodeMaterial({ color: 0xffffff });

  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load texture asynchronously (function stays synchronous)
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    }).catch(() => {
      // Fail silently – keep plain material
    });
  }

  // Apply cinematic primitives if any
  const primitiveHandles = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const handler = ctx.primitives[prim.name];
      if (handler) {
        const result = handler(mesh, prim.params ?? {});
        if (result) {
          primitiveHandles.push(result);
        }
      }
    }
  }

  // Text handling (none expected for this node, but keep pattern)
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    if (item && typeof item.text === 'string') {
      const textObj = ctx.fontAtlas.createText(item.text, {
        fontSize: item.typography?.fontSize,
        color: item.role?.color ?? '#e8ecf2',
        align: 'left',
      });
      root.add(textObj);
    }
  }

  // Set up userData with empty handlers and cleanup
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    // Dispose material and geometry
    material.dispose();
    geometry.dispose();

    // Cleanup primitives
    for (const ph of primitiveHandles) {
      if (ph && typeof ph.cleanup === 'function') {
        ph.cleanup();
      }
    }

    // Kill any GSAP timelines (none expected here)
    gsap.globalTimeline.clear(); // safe no‑op if none
  };

  return root;
}
